/* Pixel Memory Match - cohesive palette */
:root {
  --bg: #1e1e2f;
  --surface: #2a2a40;
  --primary: #f7b731;
  --secondary: #4ecdc4;
  --accent: #ff6b6b;
  --text: #f0f0f0;
  --card-back: #3a3a5a;
  --card-border: #5a5a7a;
  --card-radius: 8px;
  --font-size: 18px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: var(--font-size);
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  line-height: 1.5;
}

.game-container {
  background: var(--surface);
  border-radius: 16px;
  padding: 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

header h1 {
  font-size: 1.8rem;
  text-align: center;
  color: var(--primary);
  letter-spacing: 1px;
}

.subtitle {
  text-align: center;
  color: var(--secondary);
  font-size: 1rem;
  margin-top: 4px;
}

.status {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 1.1rem;
  padding: 8px 12px;
  background: var(--bg);
  border-radius: 8px;
  min-height: 48px;
}

#moves {
  font-weight: 600;
  color: var(--primary);
}

#win-message {
  color: var(--secondary);
  font-weight: 700;
  animation: pulse 1s infinite alternate;
}

.hidden {
  display: none;
}

@keyframes pulse {
  from { opacity: 0.7; }
  to { opacity: 1; }
}

.game-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  aspect-ratio: 1 / 1;
  max-width: 500px;
  margin: 0 auto;
  width: 100%;
}

.card {
  background: var(--card-back);
  border: 3px solid var(--card-border);
  border-radius: var(--card-radius);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0;
  transition: transform 0.2s, border-color 0.2s, background 0.2s;
  position: relative;
  aspect-ratio: 1 / 1;
  padding: 0;
  outline: none;
  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.05);
}

.card:hover:not(.matched):not(.flipped) {
  border-color: var(--primary);
  transform: scale(1.03);
}

.card:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.card:active:not(.matched):not(.flipped) {
  transform: scale(0.97);
}

.card.flipped,
.card.matched {
  background: var(--surface);
  border-color: var(--secondary);
  cursor: default;
}

.card.matched {
  border-color: var(--primary);
  box-shadow: 0 0 12px var(--primary);
}

/* Pixel-art style color swatch */
.card .color-swatch {
  width: 60%;
  height: 60%;
  border-radius: 4px;
  display: none;
  image-rendering: pixelated;
  box-shadow: 0 0 0 2px rgba(0, 0, 0, 0.3);
}

.card.flipped .color-swatch,
.card.matched .color-swatch {
  display: block;
}

.new-game-btn {
  background: var(--primary);
  color: var(--bg);
  border: none;
  border-radius: 8px;
  padding: 14px 28px;
  font-size: 1.1rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  align-self: center;
  min-width: 160px;
  letter-spacing: 0.5px;
}

.new-game-btn:hover {
  background: #ffd166;
}

.new-game-btn:focus-visible {
  outline: 3px solid var(--secondary);
  outline-offset: 3px;
}

.new-game-btn:active {
  transform: scale(0.96);
}

/* Responsive adjustments for 360px */
@media (max-width: 480px) {
  .game-container {
    padding: 16px;
    gap: 14px;
  }

  header h1 {
    font-size: 1.4rem;
  }

  .game-board {
    gap: 6px;
  }

  .card {
    border-width: 2px;
  }

  .status {
    font-size: 1rem;
    flex-direction: column;
    gap: 4px;
    text-align: center;
  }

  .new-game-btn {
    padding: 12px 20px;
    font-size: 1rem;
    width: 100%;
  }
}

@media (max-width: 360px) {
  .game-container {
    padding: 12px;
  }
  .game-board {
    gap: 4px;
  }
}

(() => {
  'use strict';

  const COLORS = [
    '#f7b731',
    '#4ecdc4',
    '#ff6b6b',
    '#a06cd5',
    '#f78fb3',
    '#45aaf2',
    '#fed330',
    '#26de81'
  ];

  const board = document.getElementById('game-board');
  const movesEl = document.getElementById('moves');
  const winMessage = document.getElementById('win-message');
  const newGameBtn = document.getElementById('new-game');

  let deck = [];
  let flipped = [];
  let matched = 0;
  let moves = 0;
  let lockBoard = false;

  function shuffle(array) {
    for (let i = array.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [array[i], array[j]] = [array[j], array[i]];
    }
    return array;
  }

  function buildDeck() {
    const pairs = COLORS.flatMap((color) => [color, color]);
    return shuffle(pairs);
  }

  function renderBoard() {
    board.innerHTML = '';
    deck.forEach((color, index) => {
      const card = document.createElement('button');
      card.className = 'card';
      card.dataset.color = color;
      card.dataset.index = index;
      card.setAttribute('aria-label', 'Hidden card');
      card.setAttribute('role', 'gridcell');

      const swatch = document.createElement('span');
      swatch.className = 'color-swatch';
      swatch.style.backgroundColor = color;
      card.appendChild(swatch);

      card.addEventListener('click', () => onCardClick(card));
      board.appendChild(card);
    });
  }

  function onCardClick(card) {
    if (lockBoard) return;
    if (card.classList.contains('flipped') || card.classList.contains('matched')) return;

    card.classList.add('flipped');
    card.setAttribute('aria-label', 'Flipped card');
    flipped.push(card);

    if (flipped.length === 2) {
      moves++;
      movesEl.textContent = `Moves: ${moves}`;
      checkMatch();
    }
  }

  function checkMatch() {
    const [first, second] = flipped;
    if (first.dataset.color === second.dataset.color) {
      first.classList.add('matched');
      second.classList.add('matched');
      first.setAttribute('aria-label', 'Matched card');
      second.setAttribute('aria-label', 'Matched card');
      matched++;
      flipped = [];
      if (matched === COLORS.length) {
        winMessage.classList.remove('hidden');
        newGameBtn.focus();
      }
    } else {
      lockBoard = true;
      setTimeout(() => {
        first.classList.remove('flipped');
        second.classList.remove('flipped');
        first.setAttribute('aria-label', 'Hidden card');
        second.setAttribute('aria-label', 'Hidden card');
        flipped = [];
        lockBoard = false;
      }, 800);
    }
  }

  function newGame() {
    deck = buildDeck();
    flipped = [];
    matched = 0;
    moves = 0;
    lockBoard = false;
    movesEl.textContent = 'Moves: 0';
    winMessage.classList.add('hidden');
    renderBoard();
  }

  newGameBtn.addEventListener('click', newGame);

  // Initialize
  newGame();
})();
